#nullable enable
using Marten;
using Wolverine.Http;
using Campaigns.Contracts;

namespace Campaigns.Slices.Campaigns;

/// <summary>The generated messageId, so a caller can go on to record outcomes against it.</summary>
public sealed record QueuedMessage(Guid MessageId);

/// <summary>
/// A CREATE slice whose rule lives in ANOTHER stream — which is the interesting shape here.
///
/// "A message cannot be queued to a closed campaign" is a fact about the Campaign stream, and this slice
/// writes the Message stream. So the Campaign stream is READ and never written: one command, one
/// swimlane. <c>session.Events.FetchLatest&lt;T&gt;</c> is that read, and it lives on
/// <c>IDocumentSession.Events</c> — not on a query session's.
///
/// The fold it reads is <c>CloseCampaignState</c>, another slice's, reused unchanged because the question
/// is literally the same question.
///
/// TAKES THE SESSION AND APPENDS DIRECTLY, rather than returning <c>(IResult, IStartStream)</c>. A
/// returned <c>IStartStream</c> slot cannot be null — Wolverine hands whatever is in it to Marten, and
/// null arrives as an ArgumentNullException from deep inside Marten. There is no empty IStartStream the
/// way <c>Events</c> has an empty collection, so a create slice that can REFUSE has no null-safe return
/// shape. Appending on the session and returning only the response is the honest form; AutoApplyTransactions
/// commits it.
/// </summary>
public static class QueueMessageEndpoint
{
    public const string Route = "/messages";

    [WolverinePost(Route)]
    public static async Task<IResult> Queue(QueueMessage command, IDocumentSession session)
    {
        // The cross-stream READ. FetchLatest on an unregistered type folds it live, which is all this
        // needs — there is no reason to materialise a projection to answer one question once.
        var campaign = await session.Events.FetchLatest<CloseCampaignState>(command.CampaignId);

        if (campaign is not { Exists: true })
            return Rejections.Problem("CampaignNotOpen",
                $"No campaign {command.CampaignId} exists.");

        if (campaign.Closed)
            return Rejections.Problem("CampaignNotOpen",
                $"Campaign {command.CampaignId} is closed, so nothing more can be queued to it.");

        // terminal="messageId:generated", terminal="senderId:actor", terminal="queuedAt:clock". The sender
        // would come from the authenticated principal; there is no authentication in this model, so a
        // supplied value is honoured and that is stated rather than hidden.
        var messageId = command.MessageId == Guid.Empty ? Guid.NewGuid() : command.MessageId;

        var queued = new MessageQueued(
            messageId, command.CampaignId, command.SenderId, command.Subject,
            command.Recipients, DateTimeOffset.UtcNow);

        session.Events.StartStream<RecordOutcomeState>(messageId, queued);

        return Results.Ok(new QueuedMessage(messageId));
    }
}
